CREATE TABLE audit_log (id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, actor_user_id TEXT, actor_username TEXT, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, resource_name TEXT, server_id TEXT, result TEXT NOT NULL CHECK(result IN ('success','failure')), remote_ip TEXT, metadata_json TEXT, error_code TEXT, error_summary TEXT);
CREATE INDEX audit_log_timestamp_idx ON audit_log(timestamp DESC,id DESC); CREATE INDEX audit_log_actor_idx ON audit_log(actor_user_id); CREATE INDEX audit_log_action_idx ON audit_log(action); CREATE INDEX audit_log_resource_idx ON audit_log(resource_type,resource_id); CREATE INDEX audit_log_server_idx ON audit_log(server_id);
